mapper.select:
SELECT e.rel_id AS relId, c.course_id AS courseId, c.course_code AS courseCode, c.course_name AS courseName, c.credit AS credit, c.course_type AS courseType, c.teacher_id AS teacherId, t.teacher_name AS teacherName, c.semester AS semester, e.score AS score, e.rel_status AS relStatus FROM edu_student_course e JOIN edu_course c ON e.course_id = c.course_id AND c.course_deleted = 0 LEFT JOIN edu_teacher t ON c.teacher_id = t.teacher_id AND t.teacher_deleted = 0 WHERE e.student_id = #{studentId}
AND e.rel_status = #{relStatus}
AND c.course_name LIKE CONCAT('%', #{courseName}, '%')
AND c.course_type = #{courseType}
ORDER BY c.course_code

SELECT e.rel_id AS relId, s.student_id AS studentId, s.student_no AS studentNo, s.student_name AS studentName, s.gender AS gender, cl.class_name AS className, e.score AS score, e.rel_status AS relStatus, e.gmt_create AS gmtCreate FROM edu_student_course e JOIN edu_student s ON e.student_id = s.student_id AND s.student_deleted = 0 LEFT JOIN edu_class cl ON s.class_id = cl.class_id AND cl.class_deleted = 0 WHERE e.course_id = #{courseId}
AND e.rel_status = #{relStatus}
AND s.student_name LIKE CONCAT('%', #{studentName}, '%')
AND s.student_no LIKE CONCAT('%', #{studentNo}, '%')
ORDER BY s.student_no
